SELECT k.id,'g5e-1-1','coktan_secmeli','“You must raise your hand.” ne demektir?','["Elini kaldırmalısın.","Koşmalısın.","Sınıftan çıkmalısın.","Kitabı kapatmalısın."]',0,'İngilizce ifade bağlama göre anlaşılır ve kullanılır.',1,1,1 FROM ders_konulari k INNER JOIN dersler d ON d.id=k.ders_id WHERE k.kademe_kodu='temel_egitim' AND k.sinif_seviyesi=5 AND k.konu_kodu='eng5-rules' AND (d.kod='ingilizce' OR d.ad='İngilizce') ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap_indeksi=VALUES(dogru_cevap_indeksi),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;

