SELECT k.id,'g5e-1-2','coktan_secmeli','“You mustn''t run in the corridor.” ne anlatır?','["Koridorda koşmalısın.","Koridorda beklemelisin.","Koridorda koşmamalısın.","Koridoru temizlemelisin."]',2,'İngilizce ifade bağlama göre anlaşılır ve kullanılır.',1,2,1 FROM ders_konulari k INNER JOIN dersler d ON d.id=k.ders_id WHERE k.kademe_kodu='temel_egitim' AND k.sinif_seviyesi=5 AND k.konu_kodu='eng5-rules' AND (d.kod='ingilizce' OR d.ad='İngilizce') ON DUPLICATE KEY UPDATE soru=VALUES(soru),secenekler_json=VALUES(secenekler_json),dogru_cevap_indeksi=VALUES(dogru_cevap_indeksi),aciklama=VALUES(aciklama),zorluk=VALUES(zorluk),sira=VALUES(sira),aktif=1;

